\copy (SELECT ticker, trade_date, open_price, high_price, low_price, close, volume FROM mi_daily_closes WHERE ticker IN ('AAOI','ABCL','ABNB','ABVX','ACN','ADVB','AEHR','AESI','AEVA','AGX','AKAM','ALAB','ALGM','AMD','AMKR','AMLX','APLD','ARGX','ARM','ARQQ','ASPN','ASX','AVAH','AVGU','BE','BFLY','BLZE','BSP','BULL','BW','CAR','CBRS','CCL','CDNA','CEG','CGEM','CHPT','CHRN','CIFR','CLS','CRWD','CRWG','DCTH','DFTX','DG','EIKN','ERO','FLY','FRMI','GDC','GKOS','GMAB','GNRC','HAE','HOOD','HPE','HTFL','HUM','HURN','HUT','IBTA','INIO','INTC','IONQ','IPCX','IREN','IRON','ITUB','JLHL','KOD','KRO','LIFE','LPTH','MAN','MANE','MRAM','MRLN','MRNA','MRVI','MRVL','MSTR','MU','MXL','NBIS','NIQ','NU','NUAI','NVTS','NVTX','ODD','OKTA','OMER','ONON','PBR','PENG','PHVS','PLTR','QBTS','QCOM','QH','QTTB','QURE','RARE','REGN','RNG','ROIV','RRC','RUM','RXT','SBAC','SCSC','SEI','SIG','SMCI','SMTC','SNDK','SNOW','SNPS','SOFI','SOLS','SPCX','SRRK','STRL','TBBB','TDIC','TEAM','TEM','TLN','TWST','UMC','USAR','UUUU','VEEE','VEEV','VICR','VRT','VST','WOLF','WYFI','YOU') AND trade_date <= DATE '2026-11-02' ORDER BY ticker, trade_date) TO STDOUT WITH CSV HEADER
